-- composition of rule kernels aggregate_function_rewriter x empty_result_pullup (duckdb), template graft_exists
WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 5) SELECT FALSE AS c0, TRUE AS c1, ARRAY['1'::text] AS c2 UNION (SELECT FALSE AS c0, TRUE AS c1, []::text[] AS c2 FROM (SELECT * FROM t4 WHERE EXISTS (SELECT 1 FROM (SELECT a1.c0 AS c0, a1.c0 AS c1, AVG (41) AS c2, AVG ((-1.5)::float8) AS c3 FROM t0 AS a1 GROUP BY a1.c0) AS kb) OR NOT EXISTS (SELECT 1 FROM (SELECT a1.c0 AS c0, a1.c0 AS c1, AVG (41) AS c2, AVG ((-1.5)::float8) AS c3 FROM t0 AS a1 GROUP BY a1.c0) AS kb)) AS a1 WHERE NULL::boolean EXCEPT (SELECT FALSE AS c0, FALSE AS c1, ARRAY['1'::text] AS c2 UNION SELECT TRUE AS c0, TRUE AS c1, ARRAY['1'::text] AS c2));
-- pgfuzz:check kernel:graft_exists WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 5) SELECT FALSE AS c0, TRUE AS c1, ARRAY['1'::text] AS c2 UNION (SELECT FALSE AS c0, TRUE AS c1, []::text[] AS c2 FROM t4 AS a1 WHERE NULL::boolean EXCEPT (SELECT FALSE AS c0, FALSE AS c1, ARRAY['1'::text] AS c2 UNION SELECT TRUE AS c0, TRUE AS c1, ARRAY['1'::text] AS c2))
